// ai-scheduling-workflow.ts — PURE recommendation workflow. The state machine structurally enforces the approval chain:
// the only path to 'applied' is accepted → application_pending → applied, and when a change touches a confirmed
// appointment the chain MUST pass through customer_approval_required → customer_approved first. Customer consent is an
// explicit external input (recordCustomerDecision) — never generated by the AI. A customer proposal PRESERVES the original
// appointment until the customer approves. Expired recommendations cannot advance.

export type RecState =
  | 'generated' | 'review_required' | 'review_in_progress'
  | 'accepted' | 'partially_accepted' | 'rejected' | 'needs_revision'
  | 'customer_approval_required' | 'customer_approved'
  | 'application_pending' | 'applied' | 'application_failed'
  | 'expired' | 'superseded' | 'rolled_back';

export type RecEvent =
  | 'submit_for_review' | 'start_review' | 'accept' | 'partial_accept' | 'reject' | 'return'
  | 'customer_approve' | 'customer_reject' | 'queue_application' | 'apply_ok' | 'apply_fail' | 'retry'
  | 'rollback' | 'expire' | 'supersede';

export interface TransitionCtx { requiresCustomerApproval?: boolean }

const TABLE: Partial<Record<RecState, Partial<Record<RecEvent, RecState | ((c: TransitionCtx) => RecState)>>>> = {
  generated: { submit_for_review: 'review_required', supersede: 'superseded', expire: 'expired' },
  review_required: { start_review: 'review_in_progress', supersede: 'superseded', expire: 'expired' },
  review_in_progress: {
    accept: (c) => (c.requiresCustomerApproval ? 'customer_approval_required' : 'accepted'),
    partial_accept: 'partially_accepted', reject: 'rejected', return: 'needs_revision', expire: 'expired',
  },
  partially_accepted: { accept: (c) => (c.requiresCustomerApproval ? 'customer_approval_required' : 'accepted'), reject: 'rejected', expire: 'expired' },
  customer_approval_required: { customer_approve: 'customer_approved', customer_reject: 'rejected', expire: 'expired' },
  accepted: { queue_application: 'application_pending', expire: 'expired' },
  customer_approved: { queue_application: 'application_pending', expire: 'expired' },
  application_pending: { apply_ok: 'applied', apply_fail: 'application_failed' },
  application_failed: { retry: 'application_pending' },
  applied: { rollback: 'rolled_back' },
  needs_revision: { submit_for_review: 'review_required', expire: 'expired' },
};

export interface TransitionResult { ok: boolean; state: RecState; error?: string }
export function transition(state: RecState, event: RecEvent, ctx: TransitionCtx = {}): TransitionResult {
  const next = TABLE[state]?.[event];
  if (next == null) return { ok: false, state, error: `invalid_transition:${state}->${event}` };
  return { ok: true, state: typeof next === 'function' ? next(ctx) : next };
}

export const isTerminal = (s: RecState) => (['applied', 'rejected', 'expired', 'superseded', 'rolled_back'] as RecState[]).includes(s);
/** A recommendation may be applied only from application_pending — which is only reachable after accepted or
 *  customer_approved. There is no edge that jumps review/generation straight to applied. */
export const canApply = (s: RecState) => s === 'application_pending';

// ── customer proposal (original preserved until approval) ─────────────────────
export type ProposalStatus = 'proposed' | 'customer_notified' | 'customer_approved' | 'customer_rejected' | 'expired' | 'applied';
export interface CustomerProposal {
  appointmentId: string; recommendationId: string;
  proposedStart: string; proposedEnd: string; proposedTechnicianId: string | null;
  status: ProposalStatus; originalPreserved: boolean; expiresAtMs: number;
}

export function createProposal(input: { appointmentId: string; recommendationId: string; proposedStart: string; proposedEnd: string; proposedTechnicianId?: string | null; nowMs: number; ttlMs?: number }): CustomerProposal {
  return {
    appointmentId: input.appointmentId, recommendationId: input.recommendationId,
    proposedStart: input.proposedStart, proposedEnd: input.proposedEnd, proposedTechnicianId: input.proposedTechnicianId ?? null,
    status: 'proposed', originalPreserved: true,                    // the confirmed appointment is untouched until approval
    expiresAtMs: input.nowMs + (input.ttlMs ?? 24 * 60 * 60 * 1000),
  };
}

/** Record the CUSTOMER's explicit decision (arriving from an authorized channel). The `approved` flag is external input —
 *  the AI never sets it. Until approved, originalPreserved stays true. */
export function recordCustomerDecision(proposal: CustomerProposal, approved: boolean, nowMs: number): { proposal: CustomerProposal; error?: string } {
  if (nowMs >= proposal.expiresAtMs) return { proposal: { ...proposal, status: 'expired' }, error: 'expired' };
  if (proposal.status !== 'proposed' && proposal.status !== 'customer_notified') return { proposal, error: 'not_pending' };
  return { proposal: { ...proposal, status: approved ? 'customer_approved' : 'customer_rejected', originalPreserved: !approved } };
}

// ── staff decision audit ──────────────────────────────────────────────────────
export interface StaffDecision { userId: string; action: 'accept' | 'partial_accept' | 'reject' | 'return' | 'edit' | 'dismiss'; reason?: string | null; at: string; editedProposal?: unknown }
export interface DecisionRecord { action: string; userId: string; reason: string | null; at: string; before: RecState; after: RecState }

/** Apply a staff decision to a recommendation, producing the next state + an audit record. Edits require a reason. */
export function applyStaffDecision(state: RecState, decision: StaffDecision, ctx: TransitionCtx = {}): { state: RecState; audit: DecisionRecord; error?: string } {
  const eventMap: Record<StaffDecision['action'], RecEvent | null> = { accept: 'accept', partial_accept: 'partial_accept', reject: 'reject', return: 'return', edit: null, dismiss: 'reject' };
  const audit = (after: RecState): DecisionRecord => ({ action: decision.action, userId: decision.userId, reason: decision.reason ?? null, at: decision.at, before: state, after });
  if (decision.action === 'edit') return { state, audit: audit(state), error: decision.reason ? undefined : 'edit_requires_reason' };  // edit stays in review; must be justified
  const ev = eventMap[decision.action];
  if (!ev) return { state, audit: audit(state), error: 'unsupported' };
  const t = transition(state, ev, ctx);
  return { state: t.state, audit: audit(t.state), error: t.ok ? undefined : t.error };
}
